const { log, i18n, events, exec, util } = require("@node-red/util");
const { v4: uuidv } = require('uuid')

var runtime;
let _module = "@runtime/lib/api/causeway"
function init(_runtime) {
    log.info(`${_module} initialized causeway runtime `)
    runtime = _runtime
}

async function getContext(activeWorkspace) {
    let ctx = runtime.nodes.getContext(activeWorkspace)
    return ctx
}


function getContextValue(activeWorkspace, value)
{
    try{
        let ctx=runtime.nodes.getContext(activeWorkspace)
        // console.log(`Context value  for ${activeWorkspace}`, ctx.get(value))
        return ctx.get(value)
    }catch(exception){
        throw exception
    }
}
module.exports = {
    init: init,
    getContext: getContext,
    getContextValue: getContextValue,
}